5	namespace AtrioTeam\DigitalHub\Tags\Filament\Resources\Schemas;
6	
7	use AtrioTeam\DigitalHub\Metadata\Filament\Schemas\MetadataSection;
8	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\NameAndId;
9	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
10	use AtrioTeam\DigitalHub\Tags\Support\TaggableEntities;
11	use Filament\Forms\Components\Hidden;
12	use Filament\Forms\Components\Select;
13	use Filament\Schemas\Schema;
14	
15	class TagGroupForm
16	{
17	    /**
18	     * Il `target` non è più scelto dall'utente ma fissato dalla risorsa: i gruppi
19	     * entità e i gruppi asset hanno resource distinte (TagGroupResource /
20	     * AssetTagGroupResource), ognuna forza il proprio target via campo nascosto.
21	     */
22	    public static function configure(Schema $schema, TagTarget $target = TagTarget::Entity): Schema
23	    {
24	        return $schema
25	            ->components([
26	                NameAndId::make($schema),
27	
28	                // owner al quale il gruppo è legato (alias config-driven)
29	                Select::make('entity_type')
30	                    ->label(__('digital-hub::tag_group.fields.entity_type'))
31	                    ->options(TaggableEntities::options())
32	                    ->required()
33	                    ->native(false),
34	
35	                // target fissato dalla risorsa (entità o asset), non modificabile
36	                Hidden::make('target')
37	                    ->default($target->value),
38	
39	                MetadataSection::make(),
40	            ]);
41	    }
42	}
