1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Tags\Models;
6	
7	use AtrioTeam\DigitalHub\Identity\Concerns\HasGlobalId;
8	use AtrioTeam\DigitalHub\Identity\Concerns\HasMetadata;
9	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
10	use AtrioTeam\DigitalHub\Tags\Support\TaggableEntities;
11	use Illuminate\Database\Eloquent\Model;
12	use Illuminate\Database\Eloquent\Relations\HasMany;
13	use Spatie\Translatable\Attributes\Translatable;
14	use Spatie\Translatable\HasTranslations;
15	
16	/**
17	 * Gruppo tag di primo livello, filtrato per tipo di owner via `entity_type`
18	 * (morph alias, es. "product"). Contiene le categorie, che contengono i tag.
19	 * `target` determina il modello taggabile effettivo dei suoi tag:
20	 * - Entity: il record dell'entità (es. Product);
21	 * - Asset:  il Media posseduto da un'entità di quel tipo.
22	 *
23	 * @property int $id
24	 * @property string $entity_type
25	 * @property TagTarget $target
26	 */
27	#[Translatable('name')]
28	class TagGroup extends Model
29	{
30	    use HasGlobalId;
31	    use HasMetadata;
32	    use HasTranslations;
33	
34	    protected $guarded = [];
35	
36	    protected $table = 'tag_groups';
37	
38	    protected $casts = [
39	        'target' => TagTarget::class,
40	    ];
41	
42	    /**
43	     * @return HasMany<TagCategory, $this>
44	     */
45	    public function categories(): HasMany
46	    {
47	        return $this->hasMany(TagCategory::class, 'tag_group_id');
48	    }
49	
50	    /**
51	     * Classe del modello taggabile dai tag di questo gruppo, derivata dal target:
52	     * asset -> Media (config media-library); entity -> modello dell'entità.
53	     *
54	     * @return class-string<Model>
55	     */
56	    public function taggableModelClass(): string
57	    {
58	        if ($this->target === TagTarget::Asset) {
59	            $mediaModel = config('media-library.media_model');
60	            assert(is_string($mediaModel) && is_subclass_of($mediaModel, Model::class));
61	
62	            return $mediaModel;
63	        }
64	
65	        return TaggableEntities::modelClass($this->entity_type);
66	    }
67	}
