1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Tags\Filament\Resources;
6	
7	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
8	use AtrioTeam\DigitalHub\Tags\Filament\Resources\Pages\ListTagGroups;
9	use AtrioTeam\DigitalHub\Tags\Filament\Resources\Schemas\TagGroupForm;
10	use AtrioTeam\DigitalHub\Tags\Filament\Resources\Tables\TagGroupsTable;
11	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
12	use BackedEnum;
13	use Filament\Resources\Resource;
14	use Filament\Schemas\Schema;
15	use Filament\Support\Icons\Heroicon;
16	use Filament\Tables\Table;
17	use Illuminate\Database\Eloquent\Builder;
18	use Override;
19	
20	class TagGroupResource extends Resource
21	{
22	    protected static ?string $model = TagGroup::class;
23	
24	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedRectangleStack;
25	
26	    protected static ?string $recordTitleAttribute = 'name';
27	
28	    // dopo le anagrafiche app (Product=100 … Material=106): il gruppo tag chiude
29	    // la lista. Valore fisso perché il core non può referenziare le resource app.
30	    protected static ?int $navigationSort = 107;
31	
32	    #[Override]
33	    public static function getNavigationGroup(): ?string
34	    {
35	        return __('digital-hub::entities.navigation_label');
36	    }
37	
38	    #[Override]
39	    public static function getModelLabel(): string
40	    {
41	        return __('digital-hub::tag_group.model');
42	    }
43	
44	    #[Override]
45	    public static function getPluralModelLabel(): string
46	    {
47	        return __('digital-hub::tag_group.model_plural');
48	    }
49	
50	    public static function form(Schema $schema): Schema
51	    {
52	        return TagGroupForm::configure($schema, TagTarget::Entity);
53	    }
54	
55	    public static function table(Table $table): Table
56	    {
57	        return TagGroupsTable::configure($table);
58	    }
59	
60	    /**
61	     * Solo i gruppi legati alle anagrafiche: i gruppi con target asset hanno la
62	     * loro resource dedicata (AssetTagGroupResource).
63	     *
64	     * @return Builder<TagGroup>
65	     */
66	    #[Override]
67	    public static function getEloquentQuery(): Builder
68	    {
69	        /** @var Builder<TagGroup> $query */
70	        $query = parent::getEloquentQuery();
71	
72	        return $query->where('target', TagTarget::Entity);
73	    }
74	
75	    public static function getRelations(): array
76	    {
77	        return [];
78	    }
79	
80	    public static function getPages(): array
81	    {
82	        return [
83	            'index' => ListTagGroups::route('/'),
84	        ];
85	    }
86	}
