34	/**
35	 * A simple Filament plugin to configure the panel via this package.
36	 */
37	class DigitalHubPlugin implements Plugin
38	{
39	    public static function make(): static
40	    {
41	        /** @var static $plugin */
42	        $plugin = app(static::class);
43	
44	        return $plugin;
45	    }
46	
47	    public function getId(): string
48	    {
49	        return 'digital-hub';
50	    }
