52	    public function register(Panel $panel): void
53	    {
54	        // Pagine di autenticazione con layout "simple" a cui applicare lo
55	        // sfondo custom: login e recupero password (richiesta link + reset).
56	        $authPages = [
57	            Login::class,
58	            RequestPasswordReset::class,
59	            ResetPassword::class,
60	        ];
61	
62	        $panel
63	            ->plugin(MinimalTheme::make())
64	            ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
65	            ->font('Open Sans')
66	            ->pages([
67	                Catalog::class,
68	                AssetManager::class,
69	                ManageGeneralSettings::class,
70	            ])
71	            // Taxonomy tag (gruppo -> categoria -> tag). Le due nidificate restano
72	            // nascoste dalla nav (parent registration): in sidebar solo i gruppi.
73	            // Due alberi paralleli scopati per target: anagrafiche e asset.
74	            ->resources([
75	                TagGroupResource::class,
76	                TagCategoryResource::class,
77	                TagResource::class,
78	                AssetTagGroupResource::class,
79	                AssetTagCategoryResource::class,
80	                AssetTagResource::class,
81	            ])
82	            // Voce "Impostazioni" nello user menu (dropdown del badge utente),
83	            // non in sidebar (la pagina ha shouldRegisterNavigation = false).
84	            // Visibile solo a chi può gestire le impostazioni.
85	            ->userMenuItems([
86	                Action::make('settings')
87	                    ->label('Impostazioni')
88	                    ->icon(Heroicon::OutlinedCog6Tooth)
89	                    ->url(fn (): string => ManageGeneralSettings::getUrl())
90	                    ->visible(fn (): bool => ManageGeneralSettings::canAccess()),
91	            ]);
92	
93	
94	
95	        // wrap del form di login in un container
96	        $panel->renderHook(
97	            PanelsRenderHook::SIMPLE_PAGE_START,
98	            fn () => '<div class="afh-login-wrapper">',
99	            scopes: $authPages,
100	        )
101	        ->renderHook(
102	            PanelsRenderHook::SIMPLE_PAGE_END,
103	            fn () => '</div>',
104	            scopes: $authPages,
105	        );
106	
107	        $this->loadSettings($panel, $authPages);
108	
109	
110	    }
