131	
132	    /**
133	     * @param array<int,class-string> $authPages
134	     */
135	    private function loadSettings(Panel $panel, array $authPages): void
136	    {
137	
138	        // Immagine di sfondo nella schermata di login. Il path è gestito dalla
139	        // pagina Impostazioni (GeneralSettings); se non impostato non viene
140	        // iniettato nulla e resta lo sfondo di default. CSS scoped alla login.
141	        $panel->renderHook(
142	            PanelsRenderHook::HEAD_END,
143	            function (): string|HtmlString {
144	                $settings = app(GeneralSettings::class);
145	
146	                if (blank($settings->login_background_path)) {
147	                    return '';
148	                }
149	
150	                $url = Storage::disk('public')->url($settings->login_background_path);
151	                $overlay = self::overlayRgba($settings->login_overlay_color, $settings->login_overlay_opacity);
152	
153	                return new HtmlString(
154	                    '<style>
155	                        .fi-simple-layout {
156	                            background-image: linear-gradient(' . $overlay . ', ' . $overlay . '), url("' . e($url) . '");
157	                            background-size: cover;
158	                            background-position: center;
159	                            background-repeat: no-repeat;
160	                        }
161	                    </style>',
162	                );
163	            },
164	            scopes: $authPages,
165	        );
166	
167	        // Colore del testo dei button primari (pieni). Gestito dalla pagina
168	        // Impostazioni; override CSS scoped ai soli .fi-color-primary, così non
169	        // tocca i button di altri colori (danger, success, ...). Iniettato su
170	        // tutte le pagine.
171	        $panel->renderHook(
172	            PanelsRenderHook::HEAD_END,
173	            function (): string|HtmlString {
174	                $color = app(GeneralSettings::class)->button_text_color;
175	
176	                if (blank($color)) {
177	                    return '';
178	                }
179	
180	                return new HtmlString(self::buttonTextColorStyle($color));
181	            },
182	        );
183	
184	        // Colore di sfondo dell'area contenuto (parte destra della pagina, non la
185	        // sidebar). Gestito dalla pagina Impostazioni; override CSS su `.fi-body`,
186	        // coperto a sinistra dalla sidebar opaca. Iniettato su tutte le pagine.
187	        $panel->renderHook(
188	            PanelsRenderHook::HEAD_END,
189	            function (): string|HtmlString {
190	                $color = app(GeneralSettings::class)->content_background_color;
191	
192	                if (blank($color)) {
193	                    return '';
194	                }
195	
196	                return new HtmlString(self::contentBackgroundStyle($color));
197	            },
198	        );
199	
200	        // Logo del panel (topbar/brand) gestito dalla pagina Impostazioni
201	        // (GeneralSettings). Se non impostato resta il default di Filament.
202	        $panel
203	            ->brandLogo(function (): HtmlString|null {
204	                $settings = app(GeneralSettings::class);
205	
206	                if (blank($settings->panel_logo_path)) {
207	                    return null;
208	                }
209	
210	                $url = Storage::disk('public')->url($settings->panel_logo_path);
211	
212	                // @phpstan-ignore argument.type
213	                return new HtmlString('<img src="' . e($url) . '" alt="' . e(config('app.name')) . '">');
214	            })
215	            ->brandLogoHeight(fn (): ?string => app(GeneralSettings::class)->panel_logo_height);
216	
217	
218	        // Il primary color (che determina anche il colore della voce attiva nella
219	        // sidebar) è gestito dalla pagina Impostazioni. Va impostato qui in
220	        // register() — non è deferibile come logo/sfondo — quindi leggiamo la
221	        // setting con un fallback al config se il DB/settings non è disponibile
222	        // (es. durante le migration o comandi console prima che la tabella esista).
223	        $primaryPalette = self::resolvePrimaryPalette();
224	        if ($primaryPalette !== null) {
225	            $panel->colors([
226	                'primary' => $primaryPalette,
227	            ]);
228	        }
229	
230	
231	
232	    }
233	
234	    /**
235	     * Risolve la palette colori (shade 50..950) da usare come primary del panel.
236	     * Ordine: setting general.primary_color (modalità "palette" = nome costante
237	     * Filament, "custom" = hex libero da cui generare la palette), poi fallback
238	     * sul config. Se la lettura delle settings fallisce (DB/tabella non
239	     * disponibile in console o durante le migration) si ricade sul config senza
240	     * sollevare eccezioni. Ritorna null se non c'è alcun colore configurato.
241	     *
242	     * @return array<int, string>|null
243	     */
244	    private static function resolvePrimaryPalette(): ?array
245	    {
246	        try {
247	            $settings = app(GeneralSettings::class);
248	
249	            if ($settings->primary_color_mode === 'custom') {
250	                if (filled($settings->primary_color_custom)) {
251	                    return \Filament\Support\Colors\Color::hex($settings->primary_color_custom);
252	                }
253	            } elseif (filled($settings->primary_color)) {
254	                return self::paletteFromName($settings->primary_color);
255	            }
256	        } catch (\Throwable) {
257	            // settings non disponibili: si usa il config
258	        }
259	
260	        $fromConfig = config('digital-hub.primary_color');
261	
262	        return is_string($fromConfig) && $fromConfig !== ''
263	            ? self::paletteFromName($fromConfig)
264	            : null;
265	    }
266	
267	    /**
268	     * Restituisce la palette di una costante colore di Filament dato il suo nome
269	     * (es. "Amber"), o null se il nome non corrisponde ad alcuna costante.
270	     *
271	     * @return array<int, string>|null
272	     */
273	    private static function paletteFromName(string $name): ?array
274	    {
275	        if (! defined(\Filament\Support\Colors\Color::class . '::' . $name)) {
276	            return null;
277	        }
278	
279	        /** @var array<int, string> $palette */
280	        $palette = \Filament\Support\Colors\Color::{$name};
281	
282	        return $palette;
283	    }
284	
285	    /**
286	     * Genera il blocco <style> che sovrascrive il colore del testo (e icona) dei
287	     * button primari (pieni). Agisce solo su `.fi-color-primary` non-outlined,
288	     * impostando le variabili CSS del testo di Filament (--text e relativi stati
289	     * hover/dark) con `!important` per battere gli stili inline del componente.
290	     * Lo sfondo dei button resta invariato.
291	     */
292	    private static function buttonTextColorStyle(string $hex): string
293	    {
294	        $text = e($hex);
295	
296	        return '<style>
297	            .fi-btn.fi-color-primary:not(.fi-outlined):not(label) {
298	                --text: ' . $text . ' !important;
299	                --hover-text: ' . $text . ' !important;
300	                --dark-text: ' . $text . ' !important;
301	                --dark-hover-text: ' . $text . ' !important;
302	            }
303	        </style>';
304	    }
305	
306	    /**
307	     * Genera il blocco <style> che sovrascrive il colore di sfondo dell'area
308	     * contenuto (la parte destra della pagina). Agisce su `.fi-body` con
309	     * `!important`, così vale sia in light che in dark mode; la sidebar, opaca,
310	     * copre la sua porzione a sinistra.
311	     */
312	    private static function contentBackgroundStyle(string $hex): string
313	    {
314	        $color = e($hex);
315	
316	        return '<style>
317	            .fi-body {
318	                background-color: ' . $color . ' !important;
319	            }
320	        </style>';
321	    }
322	
323	    /**
324	     * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
325	     * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
326	     * impostazioni. Input non validi degradano a nero/opacità clampata.
327	     */
328	    private static function overlayRgba(string $hex, float $opacity): string
329	    {
330	        $hex = ltrim($hex, '#');
331	
332	        if (strlen($hex) === 3) {
333	            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
334	        }
335	
336	        if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
337	            $hex = '000000';
338	        }
339	
340	        $r = (int) hexdec(substr($hex, 0, 2));
341	        $g = (int) hexdec(substr($hex, 2, 2));
342	        $b = (int) hexdec(substr($hex, 4, 2));
343	        $alpha = max(0.0, min(1.0, $opacity));
344	
345	        return sprintf('rgba(%d, %d, %d, %s)', $r, $g, $b, rtrim(rtrim(number_format($alpha, 2, '.', ''), '0'), '.'));
346	    }
347	
348	}
