24	class AppServiceProvider extends ServiceProvider
25	{
26	    /**
27	     * Register any application services.
28	     */
29	    public function register(): void
30	    {
31	        //
32	    }
33	
34	    /**
35	     * Bootstrap any application services.
36	     */
37	    public function boot(): void
38	    {
39	        $this->defineCatalogHierarchy();
40	
41	        // BYPASS TEMPORANEO autorizzazione — da rimuovere con la roadmap item 4
42	        // (Auth + ruoli + super-admin). Finché spatie/permission + filament-shield
43	        // non sono installati non esiste alcun permesso definito né il super-admin
44	        // gate: senza questo before, ogni can('manage_settings') (e ogni futura
45	        // policy) negherebbe a tutti, chiudendo fuori anche l'admin.
46	        // Quando si farà l'item 4, sostituire con:
47	        //   Gate::before(fn (User $user) => $user->hasRole('super-admin') ? true : null);
48	        // TODO(item 4): rimuovere questo bypass provvisorio.
49	        Gate::before(fn (User $user) => true);
50	
51	        // Morph map enforced: alias polimorfici stabili e leggibili. Serve
52	        // all'AssetManager del core, che porta il record proprietario nell'URL
53	        // via morph alias (es. /admin/assets/product/5 invece del FQCN con
54	        // backslash). enforceMorphMap impone che OGNI modello che compare in
55	        // una colonna polimorfica (media.model_type, asset_folders.folderable_type,
56	        // e in futuro activitylog subject/causer) abbia un alias qui, altrimenti
57	        // lancia: per questo sono mappati tutti i modelli di dominio.
58	        Relation::enforceMorphMap([
59	            'product' => Product::class,
60	            'product_type' => ProductType::class,
61	            'category_1' => Category1::class,
62	            'category_2' => Category2::class,
63	            'designer' => Designer::class,
64	            'material' => Material::class,
