77	
78	        if ($isDisabled && (! $this->shouldSaveRelationshipsWhenDisabled()) && (! $isSaved)) {
79	            return;
80	        }
81	
82	        if ($isHidden && (! $this->shouldSaveRelationshipsWhenHidden())) {
83	            return;
84	        }
85	
86	        if ((! $isDisabled) && (! $isHidden) && (! $isSaved)) {
87	            return;
88	        }
89	
90	        if (! ($this->getRecord()?->exists)) {
91	            return;
92	        }
93	
94	        $this->evaluate($callback);
95	    }
