97	    public function loadStateFromRelationships(bool $shouldHydrate = false): void
98	    {
99	        $callback = $this->loadStateFromRelationshipsUsing;
100	
101	        if (! $callback) {
102	            return;
103	        }
104	
105	        if (! $this->getRecord()?->exists) {
106	            return;
107	        }
108	
109	        $this->evaluate($callback);
110	
111	        if ($shouldHydrate) {
112	            $this->castStateAfterLoadingFromRelationships();
113	
114	            $this->callAfterStateHydrated();
115	
116	            foreach ($this->getChildSchemas(withHidden: true) as $childSchema) {
117	                $childSchema->callAfterStateHydrated();
118	            }
119	
120	            $this->fillStateWithNull();
