132	        $rawState = $this->getRawState();
133	        $originalRawState = $rawState;
134	
135	        foreach ($this->getStateCasts() as $stateCast) {
136	            $rawState = $stateCast->set($rawState);
137	        }
138	
139	        if ($rawState !== $originalRawState) {
140	            $this->rawState($rawState);
