121	        $category2Level = new Level(
122	            modelClass: Category2::class,
123	            resourceClass: Category2Resource::class,
124	            childLevelsFor: fn (Category2 $category2): array => [$productLevel],
125	            childrenRelation: 'subcategories', // Category1::subcategories()
126	        );
127	
128	        $category1Level = new Level(
129	            modelClass: Category1::class,
130	            resourceClass: Category1Resource::class,
131	            childLevelsFor: fn (Category1 $category1): array => [$category2Level],
132	            // root: no childrenRelation
133	        );
134	
135	        $this->app->make(CatalogHierarchy::class)->define(
136	            $category1Level,
137	            $category2Level,
138	            $productLevel,
139	        );
140	    }
